// mystery-v3.1 + mystery-v4 server rules facade. Pure module (no Deno APIs); unit-tested under Node/Vitest.
// Everything game-specific comes from the shared copies of the browser modules (supabase/functions/_shared/mystery,
// generated by `npm run sync:shared`): the offer from draft.ts, the egg tier from scoring.ts, the verdict from
// caseLogic.ts, ids/clues/suspects from the data registries. Nothing here re-implements game math.
// Cases: the session's case_id (assigned by mystery_create_session) selects the CaseDef AND the server's own answer key
// (CaseSolution from the generated registry). The answer key never leaves the server before finalize (caseReveal).
import { MYSTERY_DATA, MYSTERY_EGG, type MysteryData, type MysteryEggRules } from './mystery-registry.generated.ts';
import { DEFAULT_TUNING } from './mystery/config.ts';
import { draftOffer } from './mystery/draft.ts';
import { eggTierForSeed, round1, scoreFor, scoreV4 } from './mystery/scoring.ts';
import { evidenceSupports, isCorrectSuspect, sanitizeEvidence, solutionMatches, verdictFor } from './mystery/caseLogic.ts';
import { isCaseId } from './mystery/data/cases.ts';
import { CASE_IDS, NIGHTSHADE_IDS, MYSTERY_RULES_VERSION, SUSPECT_IDS } from './mystery/types.ts';
import type {
  CaseDef, CaseId, CaseSolution, ClueContent, ClueId, DnfReason, DuoOffer, EnemyId, MysteryRulesVersion, ScoreBreakdown, SuspectId,
  Verdict,
} from './mystery/types.ts';
import { isPokemonId } from './game/index.ts';
import { HttpError } from './errors.ts';
import { totalHits, type LiveEggTier, type MysteryProgress, type RulesContext } from './mystery-events.ts';

export { MYSTERY_RULES_VERSION, isCaseId };

/** Every rules version the server can still verify / read. New sessions are created as MYSTERY_RULES_VERSION. */
export const RULES_VERSIONS: readonly MysteryRulesVersion[] = ['mystery-v3.1', 'mystery-v4'];

/** A stored session's rules version (the DB CHECK allows exactly RULES_VERSIONS; anything else is a deployment fault). */
export function sessionRulesVersion(v: unknown): MysteryRulesVersion {
  if (!(RULES_VERSIONS as readonly unknown[]).includes(v)) throw new HttpError('INTERNAL', 'The session names an unknown rules version');
  return v as MysteryRulesVersion;
}

export function requireData(data: MysteryData | null = MYSTERY_DATA): MysteryData {
  if (!data) {
    throw new HttpError('MISCONFIGURED', 'Mystery data registries are not deployed (run npm run sync:shared, then redeploy)');
  }
  return data;
}

export function requireEggRules(egg: MysteryEggRules | null = MYSTERY_EGG): MysteryEggRules {
  if (!egg) throw new HttpError('MISCONFIGURED', 'Mystery egg tuning is not deployed (run npm run sync:shared, then redeploy)');
  return egg;
}

// ------------------------------------------------------------------------------------------------- offer
const ROLES = ['investigation', 'stealth', 'mobility', 'control', 'defense', 'support'];
const RARITIES = ['common', 'rare', 'epic'];
const STAT_KEYS = ['investigation', 'stealth', 'mobility', 'defense', 'hydeControl', 'eggProtection'] as const;
const MAX_CARD_BYTES = 8192;

/**
 * Defence in depth before anything is stored: exactly three well-formed cards for THIS seed, valid ids, no duplicate
 * pair, six stats in 1..5. A failure means the shared draft module is broken -> 500, never a stored bad offer.
 */
export function assertValidOffer(offer: DuoOffer, seed: string): void {
  const fail = (why: string): never => {
    throw new HttpError('INTERNAL', 'Offer generation failed a server sanity check', { reason: why });
  };
  if (!offer || offer.seed !== seed) fail('seed mismatch');
  if (!Array.isArray(offer.cards) || offer.cards.length !== 3) fail('not exactly three cards');
  const pairs = new Set<string>();
  for (const card of offer.cards) {
    if (!NIGHTSHADE_IDS.includes(card.characterId)) fail('unknown character');
    if (!isPokemonId(card.pokemonId)) fail('unknown pokemon');
    const key = `${card.characterId}:${card.pokemonId}`;
    if (pairs.has(key)) fail('duplicate pair');
    pairs.add(key);
    if (typeof card.duoName !== 'string' || card.duoName.length < 1 || card.duoName.length > 60) fail('duo name');
    if (!ROLES.includes(card.role)) fail('role');
    if (!RARITIES.includes(card.rarity)) fail('rarity');
    for (const k of STAT_KEYS) {
      const v = card.stats?.[k];
      if (typeof v !== 'number' || !Number.isFinite(v) || v < 1 || v > 5) fail(`stat ${k}`);
    }
    if (JSON.stringify(card).length > MAX_CARD_BYTES) fail('card too large');
  }
}

/** The three cards for a seed: the SAME pure draftOffer(seed) the browser runs, so the client cannot forge cards. */
export function computeOffer(seed: string): DuoOffer {
  requireData();
  const offer = draftOffer(seed);
  assertValidOffer(offer, seed);
  return offer;
}

// ------------------------------------------------------------------------------------------------- cases
/** The case a session plays: its public definition + the server's answer key + the culprit's clue texts. */
export interface SessionCase {
  caseDef: CaseDef;
  solution: CaseSolution;
  /** Clue texts of the session's variant (server only; released per FOUND clue, see revealedClues). */
  clues: Partial<Record<ClueId, ClueContent>>;
}

/**
 * The CaseDef + the variant of a session's stored case and murderer. A missing / mismatched answer key is a deployment
 * fault (500 MISCONFIGURED); a session created under another case version cannot be verified (409 CASE_OUTDATED).
 * `caseVersion` undefined = do not check (catalogue use). `culprit` undefined = every variant is validated and the
 * first is returned (catalogue use only — never for a session).
 */
export function resolveCase(
  caseId: unknown, caseVersion: number | undefined, data: MysteryData = requireData(), culprit?: SuspectId,
): SessionCase {
  if (!isCaseId(caseId)) throw new HttpError('INTERNAL', 'The session names an unknown case');
  const caseDef = data.cases[caseId];
  const variants = data.variants[caseId];
  const ids = culprit === undefined ? SUSPECT_IDS : [culprit];
  for (const id of ids) {
    const v = variants?.[id];
    if (!caseDef || !v || v.solution.culprit !== id || !solutionMatches(caseDef, v.solution)
      || caseDef.clues.some((c) => !v.clues[c.id])) {
      throw new HttpError('MISCONFIGURED', 'Case data and answer key are out of step (run npm run sync:shared, then redeploy)', { caseId, culprit: id });
    }
  }
  if (caseVersion !== undefined && caseVersion !== caseDef.version) {
    throw new HttpError('CASE_OUTDATED', 'This session was created for another version of its case and cannot be verified',
      { caseId, sessionVersion: caseVersion, deployedVersion: caseDef.version });
  }
  const v = variants[ids[0]];
  return { caseDef, solution: v.solution, clues: v.clues };
}

/** A uniformly random murderer for a new session (crypto RNG; independent of the seed the browser receives). */
export function drawCulprit(rand: () => number = () => crypto.getRandomValues(new Uint32Array(1))[0] / 2 ** 32): SuspectId {
  return SUSPECT_IDS[Math.min(SUSPECT_IDS.length - 1, Math.floor(rand() * SUSPECT_IDS.length))];
}

/** Case versions before 4 had ONE fixed murderer per case (sessions stored then keep it). */
const LEGACY_CULPRIT: Record<CaseId, SuspectId> = { poisoned_archive: 'thornhill', crypt_last_witness: 'galpin', midnight_signal: 'barry' };

/** The draw to offer mystery_assign_culprit for a session (only used if none is stored yet). */
export function culpritDraw(caseId: unknown, caseVersion: number | null | undefined): SuspectId {
  return isCaseId(caseId) && typeof caseVersion === 'number' && caseVersion < 4 ? LEGACY_CULPRIT[caseId] : drawCulprit();
}

export function isSuspectId(v: unknown): v is SuspectId {
  return typeof v === 'string' && (SUSPECT_IDS as readonly string[]).includes(v);
}

/** The variant clue texts the visitor may read: only the clues the server has recorded as found. */
export function revealedClues(c: SessionCase, cluesFound: readonly ClueId[]): Partial<Record<ClueId, ClueContent>> {
  const out: Partial<Record<ClueId, ClueContent>> = {};
  for (const id of cluesFound) if (c.clues[id]) out[id] = c.clues[id];
  return out;
}

/** Deployed version of every case (mystery_create_session stores the drawn case's version). Validates every key. */
export function caseVersions(data: MysteryData = requireData()): Record<CaseId, number> {
  const out = {} as Record<CaseId, number>;
  for (const id of CASE_IDS) out[id] = resolveCase(id, undefined, data).caseDef.version;
  return out;
}

/** Post-accusation reveal for the results screen (finalize response only; null for a DNF — nobody was accused). */
export interface CaseReveal {
  culprit: SuspectId;
  resolution: string;
}

export function caseReveal(c: SessionCase, outcome: 'finished' | 'dnf'): CaseReveal | null {
  return outcome === 'finished' ? { culprit: c.solution.culprit, resolution: c.solution.resolution } : null;
}

// ------------------------------------------------------------------------------------------------- rules context
export function expectedEggTier(seed: string, egg: MysteryEggRules = requireEggRules()): LiveEggTier {
  return eggTierForSeed(seed, egg.tierWeights);
}

/** The player's max HP the browser sim starts every run with (shared tuning; the same for every duo). */
export const PLAYER_MAX_HP: number = DEFAULT_TUNING.player.maxHp;

/**
 * Validation context of ONE session: the clue / suspect ids of the session's case, the seed's egg tier and the max HP
 * (a dnf 'hp_depleted' needs the recorded HP loss ≥ maxHp; enemy contract rule R7) and the SESSION's rules version
 * (mystery_sessions.rules_version; 'mystery-v4' turns on the v4 hit checks).
 */
export function rulesContext(
  seed: string, caseDef: CaseDef, egg: MysteryEggRules, maxHp: number = PLAYER_MAX_HP,
  rulesVersion: MysteryRulesVersion = MYSTERY_RULES_VERSION,
): RulesContext {
  return {
    clueIds: caseDef.clues.map((c) => c.id),
    suspectIds: caseDef.suspects.map((s) => s.id),
    eggPoints: { ...egg.points },
    expectedTier: expectedEggTier(seed, egg),
    maxHp,
    rulesVersion,
  };
}

// ------------------------------------------------------------------------------------------------- result
/** What the client CLAIMED (accusation + finish events + optional RunResult in the finalize body). Audit only. */
export interface ClientClaim {
  finishVerdict?: Verdict;
  finishScore?: number;
  accusationCorrect?: boolean;
  /** Raw evidence ids the client cited (before sanitizing). */
  accusationEvidence?: string[];
  accusationDeduction?: boolean;
  result?: Record<string, unknown>;
}

/** Server-recomputed result, camelCase, as passed to mystery_finalize_session (and returned to clients). */
export interface ServerResult {
  /** The SESSION's rules version (never the deployment's): v3.1 sessions keep the v3.1 formula. */
  rulesVersion: MysteryRulesVersion;
  caseId: CaseId;
  caseVersion: number;
  outcome: 'finished' | 'dnf';
  dnfReason: DnfReason | null;
  verdict: Verdict;
  accused: SuspectId | null;
  correct: boolean;
  /** Cited evidence after sanitizing (found clues of this case + its case-file notes; unknown / forged ids dropped). */
  evidence: string[];
  /** The sanitized evidence is exactly the case's supporting evidence (and someone was accused). */
  deductionCorrect: boolean;
  cluesFound: ClueId[];
  eggTier: LiveEggTier | null;
  eggPoints: number;
  eggSecurity: number;
  activeTimeS: number;
  score: number | null;
  catches: number;
  sightings: number;
  hintsUsed: number;
  /** mystery-v4: enemy_detected events; null for v3.1 results (never tracked). */
  detections: number | null;
  /** mystery-v4: enemy_hit events (blocked hits count); null for v3.1 results. */
  hits: number | null;
  /** DNF only: the enemy of the last enemy_hit (v4); null otherwise. */
  defeatedBy: EnemyId | null;
  /** mystery-v4 finishers: every part of the score; null for DNFs and v3.1 results. */
  scoreBreakdown: ScoreBreakdown | null;
  clientClaim: ClientClaim;
  claimMatches: boolean;
}

const near = (a: unknown, b: number | null) => (b === null ? a === null || a === undefined : typeof a === 'number' && Math.abs(a - b) < 0.05);
/** Same ids as a set (order / duplicates ignored). */
const sameIds = (a: readonly unknown[], b: readonly string[]) => {
  const x = new Set(a);
  return x.size === new Set(b).size && b.every((id) => x.has(id));
};
/** Optional claim fields: absent = nothing claimed (older client), present = must match. */
const claimOk = (claim: Record<string, unknown>, key: string, ok: (v: unknown) => boolean) => !(key in claim) || ok(claim[key]);
const BREAKDOWN_KEYS = ['delivery', 'accusation', 'clues', 'noDetection', 'noHints', 'timeBonus', 'hintPenalty', 'hitPenalty', 'total'] as const;
/** A claimed breakdown matches when every part the client sent equals the server's (null = the client claimed none). */
const sameBreakdown = (v: unknown, b: ScoreBreakdown | null) => {
  if (v === null || v === undefined) return b === null;
  if (b === null || typeof v !== 'object') return false;
  const o = v as Record<string, unknown>;
  return BREAKDOWN_KEYS.every((k) => !(k in o) || near(o[k], b[k]));
};

/**
 * Recomputes the result from validated progress with the shared scoring + case logic and the server's answer key.
 * The formula is chosen by the SESSION's rules version (`rulesVersion`, from mystery_sessions.rules_version):
 *   finished (both): activeTimeS = round1(t of egg_delivered) (the clock stops at the deposit); evidence =
 *             sanitizeEvidence(case, clues, cited) ([] when nobody was accused); verdict = verdictFor(case, solution, clues,
 *             {accused, evidence}); correct = accused is the culprit (server answer key); deductionCorrect = accused ∧
 *             evidence is exactly the supporting set
 *     v3.1:   score = scoreFor(points, t) = round1(points × 100 − activeTimeS)
 *     v4:     scoreBreakdown = scoreV4({ delivered: true, correct, cluesFound: |validated clues of this case|,
 *             detections: enemy_detected count, hintsUsed: hint_requested count, hits: enemy_hit count, activeTimeS })
 *             and score = scoreBreakdown.total (≥ 0)
 *   dnf:      score null, verdict not_accused, no evidence, eggPoints 0, activeTimeS = round1(t of the dnf event);
 *             v4: defeatedBy = dnf.by ?? the last enemy_hit's enemy (the reducer already proved they agree)
 * The client's own correct / deductionCorrect / verdict / score / evidence / counts / breakdown only feed `claimMatches`.
 */
export function computeResult(
  progress: MysteryProgress,
  kase: SessionCase,
  expectedTier: LiveEggTier | null,
  clientResult?: Record<string, unknown>,
  rulesVersion: MysteryRulesVersion = MYSTERY_RULES_VERSION,
): ServerResult {
  const { caseDef, solution } = kase;
  const term = progress.terminal;
  if (!term) throw new HttpError('RUN_NOT_FINISHED', 'No finish or dnf event has been recorded yet', { lastSeq: progress.lastSeq });
  const v4 = rulesVersion === 'mystery-v4';
  const security = Math.max(0, Math.min(100, round1(progress.eggSecurity)));
  const detections = v4 ? progress.detections ?? 0 : null;
  const hits = v4 ? totalHits(progress) : null;
  const base = {
    rulesVersion,
    caseId: caseDef.id,
    caseVersion: caseDef.version,
    cluesFound: [...progress.cluesFound],
    catches: progress.catches,
    sightings: progress.sightings,
    hintsUsed: progress.hints,
    detections,
    hits,
  };
  // v4 counts the client may claim (absent = not claimed)
  const countsOk = (c: Record<string, unknown>) => !v4 || (
    claimOk(c, 'hintsUsed', (v) => v === progress.hints)
    && claimOk(c, 'detections', (v) => v === detections)
    && claimOk(c, 'hits', (v) => v === hits)
  );

  if (term.type === 'finish') {
    const d = progress.delivered;
    const acc = progress.accusation;
    if (!d || !acc) throw new HttpError('INVALID_TRANSITION', 'finish without delivery/accusation passed validation');
    const accused = acc.suspectId;
    const cited: string[] = acc.evidence ?? []; // progress written before evidence existed has none
    const evidence = accused === null ? [] : sanitizeEvidence(caseDef, progress.cluesFound, cited);
    const verdict = verdictFor(caseDef, solution, progress.cluesFound, { suspectId: accused, evidence });
    const correct = isCorrectSuspect(solution, accused);
    const deductionCorrect = accused !== null && evidenceSupports(solution, evidence);
    const activeTimeS = round1(d.t);
    const scoreBreakdown = v4
      ? scoreV4({
        delivered: true, correct, cluesFound: progress.cluesFound.length, detections: detections ?? 0, hintsUsed: progress.hints,
        hits: hits ?? 0, activeTimeS,
      })
      : null;
    const score = scoreBreakdown ? scoreBreakdown.total : scoreFor(d.points, d.t);
    const claim: ClientClaim = {
      finishVerdict: term.claimedVerdict, finishScore: term.claimedScore, accusationCorrect: acc.claimedCorrect,
      accusationEvidence: [...cited], accusationDeduction: acc.claimedDeduction,
    };
    if (clientResult) claim.result = clientResult;
    const claimMatches = term.claimedVerdict === verdict && near(term.claimedScore, score) && acc.claimedCorrect === correct
      && acc.claimedDeduction === deductionCorrect && sameIds(cited, evidence)
      && (!clientResult || (
        clientResult.outcome === 'finished' && clientResult.verdict === verdict && near(clientResult.score, score)
        && near(clientResult.activeTimeS, activeTimeS)
        && claimOk(clientResult, 'caseId', (v) => v === caseDef.id)
        && claimOk(clientResult, 'rulesVersion', (v) => v === rulesVersion)
        && claimOk(clientResult, 'correct', (v) => v === correct)
        && claimOk(clientResult, 'deductionCorrect', (v) => v === deductionCorrect)
        && claimOk(clientResult, 'evidence', (v) => Array.isArray(v) && sameIds(v, evidence))
        && countsOk(clientResult)
        && (!v4 || claimOk(clientResult, 'scoreBreakdown', (v) => sameBreakdown(v, scoreBreakdown)))
      ));
    return {
      ...base, outcome: 'finished', dnfReason: null, verdict, accused, correct, evidence, deductionCorrect,
      eggTier: d.tier, eggPoints: d.points, eggSecurity: Math.max(0, Math.min(100, round1(d.security))), activeTimeS, score,
      defeatedBy: null, scoreBreakdown, clientClaim: claim, claimMatches,
    };
  }

  const defeatedBy: EnemyId | null = v4 ? term.by ?? progress.lastHitBy ?? null : null;
  const claim: ClientClaim = {};
  if (clientResult) claim.result = clientResult;
  return {
    ...base, outcome: 'dnf', dnfReason: term.reason, verdict: 'not_accused', accused: null, correct: false, evidence: [],
    deductionCorrect: false, eggTier: expectedTier, eggPoints: 0, eggSecurity: security, activeTimeS: round1(term.t),
    score: null, defeatedBy, scoreBreakdown: null, clientClaim: claim,
    claimMatches: !clientResult || (clientResult.outcome === 'dnf' && (clientResult.score === null || clientResult.score === undefined)
      && claimOk(clientResult, 'caseId', (v) => v === caseDef.id)
      && claimOk(clientResult, 'rulesVersion', (v) => v === rulesVersion)
      && countsOk(clientResult)
      && (!v4 || claimOk(clientResult, 'defeatedBy', (v) => (v ?? null) === defeatedBy))),
  };
}
